/* Network interface setup example for lwip_tcpip.*/
#define ${lwip_ether_name_upper:raProperty(module.middleware.lwip_ether.name_upper)}_IPADDR1  (192)
#define ${lwip_ether_name_upper}_IPADDR2  (168)
#define ${lwip_ether_name_upper}_IPADDR3  (10)
#define ${lwip_ether_name_upper}_IPADDR4  (4)
#define ${lwip_ether_name_upper}_NETMASK1 (255)
#define ${lwip_ether_name_upper}_NETMASK2 (255)
#define ${lwip_ether_name_upper}_NETMASK3 (255)
#define ${lwip_ether_name_upper}_NETMASK4 (0)
#define ${lwip_ether_name_upper}_GW1      (192)
#define ${lwip_ether_name_upper}_GW2      (168)
#define ${lwip_ether_name_upper}_GW3      (10)
#define ${lwip_ether_name_upper}_GW4      (1)

struct netif     g_${lwip_ether_name:raProperty(module.middleware.lwip_ether.name)}_netif;

void ${lwip_ether_name}_netif_setup(void);

/* Network interface setup for lwip_tcpip. */
void ${lwip_ether_name}_netif_setup(void)
{
    ip_addr_t ipaddr;
    ip_addr_t netmask;
    ip_addr_t gw;

    /* Set ip address of the board. */
    IP4_ADDR(&ipaddr, ${lwip_ether_name_upper}_IPADDR1, ${lwip_ether_name_upper}_IPADDR2, ${lwip_ether_name_upper}_IPADDR3, ${lwip_ether_name_upper}_IPADDR4);
    IP4_ADDR(&netmask, ${lwip_ether_name_upper}_NETMASK1, ${lwip_ether_name_upper}_NETMASK2, ${lwip_ether_name_upper}_NETMASK3, ${lwip_ether_name_upper}_NETMASK4);
    IP4_ADDR(&gw, ${lwip_ether_name_upper}_GW1, ${lwip_ether_name_upper}_GW2, ${lwip_ether_name_upper}_GW3, ${lwip_ether_name_upper}_GW4);

    /* Initialize netif. Please pass rm_lwip_ether_init() function and the instance of rm_lwip_ether to netif_add(). */
    netif_add(&g_${lwip_ether_name}_netif, &ipaddr, &netmask, &gw, &${lwip_ether_name}_instance, rm_lwip_ether_init, netif_input);

    /* Set netif as default and enable */
    netif_set_default(&g_${lwip_ether_name}_netif);
    netif_set_up(&g_${lwip_ether_name}_netif);
    netif_set_link_up(&g_${lwip_ether_name}_netif);
}

/* Quick tear down example for initializing lwIP core.
*  Please use this example after calling quick setup example
*/
void lwip_core_setup(void);

/* Quick tear down example for initializing lwIP core. */
void lwip_core_setup(void)
{
    /* Initializing lwIP core. */
#if NO_SYS
    lwip_init();
#else
    tcpip_init(NULL, NULL);
#endif
}

/* Quick tear down example for network interface.
*/
void ${lwip_ether_name:raProperty(module.middleware.lwip_ether.name)}_netif_teardown(void);

/* Quick tear down example for network interface. */
void ${lwip_ether_name}_netif_teardown(void)
{
    /* Tear Down netif. */
    netif_remove(&g_${lwip_ether_name}_netif);
}
